-- Tenant isolation, generated by tenantRlsSql (packages/db/src/rls.ts). test/rls-catalog.int.test.ts
-- fails if any tenant table lacks forced RLS + this policy. Tables are invisible to app_user until
-- granted here: there are no default privileges.
GRANT USAGE ON SCHEMA public TO "app_user";
--> statement-breakpoint
-- users is global (no tenant_id): plain grants, no RLS — login looks users up by email before any
-- tenant context exists.
GRANT SELECT, INSERT, UPDATE ON "users" TO "app_user";
--> statement-breakpoint
ALTER TABLE "tenants" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE "tenants" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "tenants" AS PERMISSIVE FOR ALL TO PUBLIC USING ("id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
--> statement-breakpoint
REVOKE ALL ON "tenants" FROM "app_user";
--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "tenants" TO "app_user";
